parameters.query:
select 'part_3_cancellation_risk' as query_name, 'row_count' as variable_name, count(*) as value, object_construct('source_table','production.churn.cancellation_risk') as metadata from production.churn.cancellation_risk where organization_id = {{$json.body.organization_id}}
union all select 'part_3_health_index', f.key::string, f.value, object_construct('source_table','production.customer_success.health_index_yesterday') from (select object_construct_keep_null(*) as row_data from production.customer_success.health_index_yesterday where organization_id = {{$json.body.organization_id}}) r, lateral flatten(input => r.row_data) f
union all select 'part_3_next_bill_churn', f.key::string, f.value, object_construct('source_table','production.churn.next_bill_churn_by_orgday') from (select object_construct_keep_null(*) as row_data from production.churn.next_bill_churn_by_orgday where organization_id = {{$json.body.organization_id}} qualify row_number() over (order by date desc) = 1) r, lateral flatten(input => r.row_data) f
union all select 'part_3_plan_changes', 'plan_changes', array_agg(object_construct_keep_null(*)), object_construct('source_table','production.customer_success.plan_changes') from production.customer_success.plan_changes where organization_id = {{$json.body.organization_id}};
